/**
 * SPHEREx metadata registry — browser-side loader.
 *
 * The registry (data/spherex/registry/registry.json) is generated by
 * scripts/build-spherex-registry.mjs from a timestamped IRSA TAP metadata
 * snapshot and published as a static asset at /spherex/registry.json by the
 * vite config. It is far too large to inline into the app bundle, so it is
 * fetched lazily once per page load and cached in module scope.
 *
 * Everything here is DISPLAY- and metadata-only: capability states are derived
 * from the same pure adapter + capabilitiesFor() pair the acceptance fixtures
 * were generated with, so the portal can never disagree with the fixtures.
 * Scientific availability always comes from the capability record; this module
 * gates nothing by rank or progression.
 */
import { capabilitiesFor, type Capabilities, type ObservationMetadata } from './spherex'
import { framesFromGroups, type ObservationGroup, type RegistryTargetMeta, type TargetSummary } from './irsa'

export interface StoredRegistryTarget {
  meta: RegistryTargetMeta
  truncated: boolean
  summary: TargetSummary
  wavelengthTier: 'plane-bounds' | 'wcs-wave'
  wavelengthAtTargetUm: number | null
  groups: ObservationGroup[]
}

export interface SpherexRegistry {
  adapter: string
  snapshotCapturedAt: string
  generatedAt: string
  provenance: string
  wavelengthPolicy: { planeBounds: string; wcsWave: string }
  targets: Record<string, StoredRegistryTarget>
}

const REGISTRY_URL = '/spherex/registry.json'

let cached: Promise<SpherexRegistry> | null = null

/** Fetches (once) and caches the registry. Rejects when it is not published. */
export function loadSpherexRegistry(): Promise<SpherexRegistry> {
  cached ??= fetch(REGISTRY_URL).then((response) => {
    if (!response.ok) throw new Error(`Registry unavailable (HTTP ${response.status}).`)
    return response.json() as Promise<SpherexRegistry>
  })
  return cached
}

/** Metadata frames of a stored target, best release per footprint+channel. */
export function targetFrames(target: StoredRegistryTarget): ObservationMetadata[] {
  return framesFromGroups(target.groups)
}

/** Capability record derived from the registry groups, identical to fixtures. */
export function targetCapabilities(target: StoredRegistryTarget): Capabilities {
  return capabilitiesFor(targetFrames(target))
}

export type { Capabilities }
